import React, { useEffect } from "react";
import Menu from "./Menu";

const TopBar = () => {
  useEffect(() => {
    // Purane widget ko clear karne ke liye (Cleanup)
    const container = document.getElementById("tradingview-widget");
    if (container) {
      container.innerHTML = ""; 
    }

    const script = document.createElement("script");
    script.src = "https://s3.tradingview.com/external-embedding/embed-widget-tickers.js";
    script.async = true;
    script.innerHTML = JSON.stringify({
      "symbols": [
        { "proName": "FOREXCOM:NSXUSD", "title": "NIFTY 50" },
        { "proName": "INDEX:SENSEX", "title": "SENSEX" }
      ],
      "colorTheme": "light",
      "isTransparent": true,
      "showSymbolLogo": false,
      "locale": "in"
    });

    if (container) container.appendChild(script);
  }, []);

  return (
    <div className="topbar-container" style={{ 
      display: "flex", 
      justifyContent: "space-between", 
      alignItems: "center",
      padding: "5px 20px",
      borderBottom: "1px solid #eee",
      backgroundColor: "#fff",
      height: "60px"
    }}>
      {/* Live Market Data Section */}
      <div id="tradingview-widget" style={{ 
        width: "500px", 
        overflow: "hidden" 
      }}></div>

      {/* Profile and Menu Section */}
      <Menu />
    </div>
  );
};

export default TopBar;
